{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Rufinamide, a heteroaromatic carboxamide, has an absolute oral bioavailability of 85% in humans, showing that carboxamide-bearing azoles can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C77"],
      "claim": "Niraparib, a heteroaromatic carboxamide, has an absolute oral bioavailability of 72.7% in cancer patients after a 300 mg oral dose versus IV, supporting high F for carboxamide-containing heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Emtricitabine, a nucleoside analog, has a mean absolute oral bioavailability of 93% in HIV-infected subjects, demonstrating that polar nucleosides can be highly orally bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Stavudine, a nucleoside reverse transcriptase inhibitor, has an absolute oral bioavailability of 61-78% in children, supporting high F for nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Lamivudine, a nucleoside analog, has an absolute oral bioavailability of 86-88% in adults across oral formulations, supporting high F for nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Zalcitabine, a dideoxynucleoside, had an absolute oral bioavailability of 88% in patients with AIDS/ARC, showing that even dideoxynucleosides can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Salicin, a polar glycoside, had an oral bioavailability of 43.3% in humans, supporting F above 20% for sugar-containing polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Didanosine, an acid-labile dideoxynucleoside, had F=19% in children, below the threshold; this is the main contradictory example but is mechanistically tied to acid lability and dideoxy sugar, unlike the query's full ribose.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar full-ribose nucleoside carboxamide. High-transfer human absolute bioavailability measurements for rufinamide (85%), niraparib (72.7%), emtricitabine (93%), stavudine (61-78%), lamivudine (86-88%), zalcitabine (88%), and salicin (43%) consistently support F >=20%. The only low-F analogue, didanosine, is an acid-labile dideoxynucleoside whose mechanism does not apply to the query's full ribose. Therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule.",
    "Didanosine low-F records are from acid-labile dideoxynucleosides; their transfer to the full-ribose query is uncertain.",
    "Potential effects of nucleoside transporters and first-pass metabolism on the query are not directly measured."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C40"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "nucleoside analog oral bioavailability"
    }
  ],
  "revision_action": "initial"
}

